function S = stress_model(T, m, dod)
%STRESS_MODEL  AUTO-GENERATED by C:\bitirme\ml\07_stress_model.py, do not edit by hand.
%   Hybrid cycle-ageing stress factor S(T, m, dod) per equivalent full cycle, LG M50T (Kirkaldy et al. 2024,
%   12 cycling conditions): physics (Millner-type, aging_stress.m) x exp(r(T)), r = data residual,
%   piecewise linear between the three temperature groups (the depth-2 residual tree splits only on T).
%   S(25 C, m 0.5, dod 1) = 3.3564. Damage law: fade_cyc = STRESS_A (sum S dEFC)^STRESS_Z.
%   Calendar fade (Schmalstieg 2014, NMC, literature): max(0, C1 V + C0) SCALE exp(-EA / T_K) days^EXP.
%   T [degC], m mean SOC of the half cycle [0-1], dod depth of the half cycle [0-1]

%#codegen
main_ = exp(5.2021831e-02 * (m - 0.5) / 0.25) * exp(8.2047761e-21 * max(0, T - 25.0)) ...
        * exp(2.9654845e-01 * max(0, 25.0 - T) * m);
si = 5.6490429e+01 * exp(-m / 0.1) * exp(2.2200714e-02 * (T - 25.0));
phys = exp((dod - 1) / 4.2857300e-01) * (main_ + si) / 1.3806295e+00 * exp(6.9314718e-02 * max(0, T - 42.3));
if T <= 16.5062609
    r = 0.6302895;
elseif T <= 28.5251351
    r = 0.6302895 + 6.8352831e-02 * (T - 16.5062609);
elseif T <= 41.4347280
    r = 1.4518135 + -1.2461547e-01 * (T - 28.5251351);
else
    r = -0.1569214;
end
S = phys * exp(r);
end
